#include <stdio.h>
#define N 50
int main(){int n,a[2][N],t[2][N],en[2],ex[2],f[2][N],par[2][N];printf("Stations: ");if(scanf("%d",&n)!=1||n<2||n>N)return 1;for(int l=0;l<2;l++)for(int j=0;j<n;j++)scanf("%d",&a[l][j]);for(int l=0;l<2;l++)for(int j=0;j<n-1;j++)scanf("%d",&t[l][j]);scanf("%d%d%d%d",&en[0],&en[1],&ex[0],&ex[1]);f[0][0]=en[0]+a[0][0];f[1][0]=en[1]+a[1][0];par[0][0]=0;par[1][0]=1;for(int j=1;j<n;j++){int s1=f[0][j-1]+a[0][j],x1=f[1][j-1]+t[1][j-1]+a[0][j],s2=f[1][j-1]+a[1][j],x2=f[0][j-1]+t[0][j-1]+a[1][j];f[0][j]=s1<=x1?s1:x1;par[0][j]=s1<=x1?0:1;f[1][j]=s2<=x2?s2:x2;par[1][j]=s2<=x2?1:0;printf("Station %d: L1 stay=%d transfer=%d -> %d; L2 stay=%d transfer=%d -> %d\n",j+1,s1,x1,f[0][j],s2,x2,f[1][j]);}int end0=f[0][n-1]+ex[0],end1=f[1][n-1]+ex[1],l=end0<=end1?0:1,b=end0<=end1?end0:end1,route[N];route[n-1]=l;for(int j=n-1;j>0;j--)route[j-1]=par[route[j]][j];printf("Minimum production time=%d\nRoute: Entry -> ",b);for(int j=0;j<n;j++)printf("L%d-S%d -> ",route[j]+1,j+1);puts("Exit");for(int j=1;j<n;j++)if(route[j]!=route[j-1])printf("Transfer before station %d\n",j+1);}
